response:
 It looks like you’re trying to randomly shuffle an ordered list. Here’s some code that does this for you:

function shuffle(array) {
    var j = array.length, i;
    while (j--) {
        i = Math.floor(Math.random() * j);
        swap(array, i, j);
    }
}

