using System;
using System.Linq;
using Newtonsoft.Json;

class Program
{
   static void Main()
   {
      var jsonData = @"{""year"":""2021"",""visas_issued"":4624437,""top_immigrant_countries"":{""Mexico"":1235535,""China"":555209,""India"":497499,""Philippines"":419004,""Dominican Republic"":182722},""policy_changes"":[{""date"":""January 2021"",""description"":""Suspension of entry for certain employment-based nonimmigrant visa categories""},{""date"":""February 2021"",""description"":""Repeal of the Muslim Ban""},{""date"":""March 2021"",""description"":""Creation of a task force to reunite families separated at the border""}]}";
      var data = JsonConvert.DeserializeObject<Data>(jsonData);
