      Console.WriteLine($"Top Immigrant Countries:");
      foreach(var country in data.top_immigrant_countries)
         Console.WriteLine($"{country.Key}: {country.Value}");
      Console.WriteLine($"Policy Changes:");
      foreach(var change in data.policy_changes)
         Console.WriteLine($"Date: {change.date} - Description: {change.description}");

