What is the best way to retrieve and analyze data from a JSON dataset in C#? Specifically, I need to extract the number of visas issued, the top countries with the most immigrants, and any recent policy changes affecting immigration from the following dataset:
{
  "year": 2021,
  "visas_issued": 4624437,
  "top_immigrant_countries": {
    "Mexico": 1235535,
    "China": 555209,
    "India": 497499,
    "Philippines": 419004,
    "Dominican Republic": 182722
  },
  "policy_changes": [
    {
      "date": "January 2021",
      "description": "Suspension of entry for certain employment-based nonimmigrant visa categories"
    },
    {
      "date": "February 2021",
      "description": "Repeal of the Muslim Ban"
    },
    {
      "date": "March 2021",
      "description": "Creation of a task force to reunite families separated at the border"
    }
  ]
}
Can you provide a C# code snippet that utilizes JSON data to extract the required information?

response:
 Here’s one possible solution using LINQ:
using System;
using System.IO;
using Newtonsoft.Json;
namespace ConsoleApp1 {
class Program {
    static void Main(string[] args) {
        string jsonData = File.ReadAllText("input.json");
        var jdata = JsonConvert.DeserializeObject<object>(jsonData);
        // get values from object
        var year = jdata.year;
        var visasIssued = jdata.visas_issued;
        var topImmigrantCountries = jdata.top_immigrant_countries;
        var policyChanges = jdata.policy_changes;

        // create output array to store results
        string[] resultArray = new string[4];
        resultArray[0] = $"Year: {year}";
        resultArray[1] = $"Visas Issued: {visasIssued}";
        resultArray[2] = $"Top Immigrant Countries: ";
        foreach (var country in topImmigrantCountries) {
            resultArray[2] += country + ", ";
        }
        resultArray[3] = $"Policy Changes: ";
        foreach (var change in policyChanges) {
            resultArray[3] += change.date + " - " + change.description + "\n";
        }

        // write output array to console
        Console.WriteLine("\n");
        Console.WriteLine("Output Array: ");
        Console.WriteLine(String.Join("\n", resultArray));

