import { Component } from "react";
import "./style.css";

class MyComponent extends Component {
    constructor() {
        super();
        this.state = {
            mnpStatuses: [],
        };
    }

    componentDidMount() {
        this.setState({
            mnpStatuses: [{
                portInStatus: 1
            }],
        });
    }

    render() {
        return <div>
            {this.state.mnpStatuses.map((mnpStatus) => {
                return <p>{mnpStatus.portInStatus}</p>;
            })}
        </div>;
    }
}

export default MyComponent;

